tiles=[]
for r in range(6):
 for c in range(6):
  sq={(r,c),(r+1,c),(r,c+1),(r+1,c+1)}
  if sq<=cells: tiles.append(('S',sq))
  for missing in [(r,c),(r,c+1),(r+1,c),(r+1,c+1)]:
   t=sq-{missing}
   if t<=cells: tiles.append((f'L{missing[0]-r}{missing[1]-c}',t))
sol=[]
def rec(left, chosen):
 if not left:
  sol.append(chosen.copy()); return
 x=min(left, key=lambda p:sum(p in t for _,t in tiles))
 for typ,t in tiles:
  if x in t and t<=left:
   rec(left-t, chosen+[(typ,t)])
rec(cells,[])
len(tiles),len(sol),{tuple(sorted(t for typ,t in s)) for s in sol}
